// Only this format is generated by daily attendance. Custom DAF/EMP identifiers
// retain their exact spelling; a managed prefix alone never proves an identity.
function validDailyBadge(value){
 const id=String(value??''),match=/^DA-(\d{4})(\d{2})(\d{2})-([0-9A-F]{8})$/i.exec(id);
 if(!match)return false;
 const day=match[1]+'-'+match[2]+'-'+match[3],time=Date.parse(day+'T00:00:00.000Z');
 return Number.isFinite(time)&&new Date(time).toISOString().slice(0,10)===day;
}
export const canonicalDailyBadge=value=>validDailyBadge(value)?String(value).toUpperCase():String(value??'');
export const isSystemDailyBadge=validDailyBadge;
export const isAttendanceBadge=value=>/^(?:DA|DAF|EMP)-/i.test(String(value??''));
export const sameWorkerBadge=(a,b)=>canonicalDailyBadge(a)===canonicalDailyBadge(b);
